const speakersTalks=[{author:"Julian Külshamme",id:"kulshammer",affiliate:"Uppsala",web:"https://julian-kuelshammer.github.io/",title:"Highest weight categories, $A_\\infty$-algebras, and corings",abstract:"",category:"lecture",timeIndex:1},{author:"Anya Nordskova",id:"nordskova",affiliate:"Kavli IPMU, University of Tokyo",web:"https://anyanord.ru/",title:"Around abelian envelopes of exact categories",abstract:"",category:"lecture",timeIndex:0},{author:"Toshitaka Aoki",id:"aoki",affiliate:"Kobe",title:"Reedy and quasi-hereditary structures on endomorphism algebras of interval modules",abstract:"",category:"invited",timeIndex:0},{author:"Shunsuke Hirota",id:"hirota",affiliate:"RIMS Kyoto",title:"On infinite-dimensional Khovanov arc algebras",abstract:"Khovanov introduced arc algebras using a two-dimensional TQFT\nin his construction of a categorification of tangle invariants.\nBrundan--Stroppel subsequently established a natural graded Morita\nequivalence between these algebras and certain level-two cyclotomic KLR\nalgebras of type A, revealing connections with Lie theory. Through this\nconnection, their quasi-hereditary analogues $K^m_n$, $K^\\infty_n$,\n$K^{\\pm\\infty}_n$, and $K^{\\infty}_{\\infty}$ provide diagrammatic realizations\nof various fundamental module categories arising in type A Lie theory,\ntogether with certain exact functors on them. In this talk, we will\npresent concrete examples of arc algebras, including quiver\npresentations, and illustrate phenomena specific to highest weight\ncategories beyond the finite setting.",category:"invited",timeIndex:0},{author:"Junyang Liu",id:"liu",affiliate:"Tokyo",web:"https://webusers.imj-prg.fr/~junyang.liu/",title:"$A_\\infty$-deformations of zigzag algebras via Ginzburg dg algebras",abstract:"We aim to give a short proof of the recent result due to Etgü--Lekili\n(2017) and Lekili--Ueda (2021): the zigzag algebra of any finite tree\nover a field of characteristic 0 is intrinsically formal if and only if\nthe tree is of type ADE. We also complete the proof of this result by\nconsidering a field of arbitrary characteristic for type E, which was\nstill open.",category:"invited",timeIndex:1},{author:"Hiroyuki Minamoto",id:"minamoto",affiliate:"Osaka Metropolitan",title:"Ringel duality and recollements",abstract:"",category:"invited",timeIndex:2},{author:"Haruto Murata",id:"murata",affiliate:"Tokyo",web:"https://sites.google.com/view/hmurata/home/",title:"Affine highest weight structures on module categories over quiver Hecke algebras",abstract:"The module categories over quiver Hecke algebras (or Khovanov-Lauda-Rouquier algebras) associated with symmetrizable generalized Cartan matrices provide a categorification of the quantum group. In this talk, we explain that the subcategory corresponding to the quantum unipotent subgroup determined by any element of the Weyl group is an affine highest weight category. This generalizes earlier works to arbitrary symmetrizable types and any coefficient field. The key ingredients of our proof are the explicit realization of standard modules, the injectivity of certain homomorphisms known as R-matrices, and computations in the Grothendieck ring (i.e., within the quantum group). ",category:"invited",timeIndex:0},{author:"Ryo Tomonaga",id:"tomonaga",affiliate:"Tokyo",title:"Derived Auslander-Iyama correspondence from a global dimension perspective",abstract:"",category:"invited",timeIndex:0}],groupedList=speakersTalks.reduce((res,item)=>(res["lecture"===item.category?0:1].talks.push(item),res),[{heading:"Lecture series 連続講演",talks:[]},{heading:"Invited lectures 招待講演",talks:[]}]);function talkDetails(talkData){const hasAbstract=talkData.abstract.length>0,hasTitle=talkData.title.length>0,details=document.createElement(hasAbstract?"details":"div");details.classList.add("talk_details"),details.setAttribute("id",talkData.id),details.setAttribute("aria-talkcategory",talkData.category),details.setAttribute("aria-talkorder",talkData.timeIndex);const summary=document.createElement(hasAbstract?"summary":"div");if(summary.classList.add(hasAbstract?"talk_summary":"talk_title_only"),summary.textContent=`${talkData.author} (${talkData.affiliate})`,hasTitle){const title=document.createElement("div");title.classList.add("subtitle"),title.innerHTML=talkData.title,summary.appendChild(title)}if(details.appendChild(summary),hasAbstract){const abstract=document.createElement("p");abstract.innerHTML=talkData.abstract,details.appendChild(abstract)}return details}function sortListOfTalks(talks,order="id"){let method=(a,b)=>a.id.localeCompare(b.id);switch(order){case"time":method=(a,b)=>a.timeIndex-b.timeIndex;break;case"author":method=(a,b)=>a.author.localeCompare(b.author)}return talks.toSorted(method)}function populateTalksHTML(grouped=!0,order="time"){const listDiv=document.getElementById("headingInfo_talk_list");listDiv.replaceChildren();for(const group of groupedList){const eltHeading=document.createElement("h4");eltHeading.append(group.heading);const eltList=document.createElement("ul");eltList.classList.add("compact","lineChangeAfter");for(const{author:author,affiliate:affiliate,web:web}of sortListOfTalks(group.talks)){const itm=document.createElement("li");itm.innerHTML=(web?`<a href="${web}">`:"")+author+(web?"</a>":"")+` (${affiliate})`,eltList.appendChild(itm)}listDiv.appendChild(eltHeading),listDiv.appendChild(eltList)}const mother=document.getElementById("titleAbstractDiv");mother.replaceChildren();const fullList=grouped?groupedList:{talks:speakersTalks};for(const group of fullList){const container=document.createElement("div");if(container.classList.add("clamp"),grouped){const heading=document.createElement("h3");heading.textContent=group.heading,container.append(heading)}const sorted=sortListOfTalks(group.talks,order);for(const talk of sorted)container.append(talkDetails(talk));mother.append(container)}renderMathInElement(document.body,{delimiters:[{left:"$",right:"$",display:!1}]}),document.getElementById("btnAbstractOpen").addEventListener("click",e=>{document.querySelectorAll("details.talk_details").forEach(t=>t.open=!0)})}window.onload=function(){populateTalksHTML(!0,"alpha")};